 1: ---
 2: - hosts: localhost
 3:   gather_facts: no
 4:   tasks:
 5:     - hashivault_auth_list:
 6:       register: auth_list
 7:     - assert: { that: "'token/' in auth_list.backends" }
 8:     - assert: { that: "'userpass/' not in auth_list.backends" }
 9:     - name: Delete any lingering userpass
10:       hashivault_auth_method:
11:         method_type: "userpass"
12:         state: disable
13:       failed_when: False
14:     - name: Enable userpass first time for this test
15:       hashivault_auth_method:
16:         method_type: "userpass"
17:         description: "my userpass"
18:       register: 'vault_auth'
19:     - assert: { that: "vault_auth is changed" }
20:     - assert: { that: "vault_auth.created == True" }
21:     - assert: { that: "vault_auth.failed == False" }
22:     - assert: { that: "vault_auth.rc == 0" }
23:     - hashivault_auth_list:
24:       check_mode: true
25:       register: auth_list
26:     - assert: { that: "'userpass/' in auth_list.backends" }
27:     - name: Enable userpass when it is already enabled
28:       hashivault_auth_method:
29:         method_type: "userpass"
30:         description: "my userpass"
31:       register: 'vault_auth'
32:     - assert: { that: "vault_auth is not changed" }
33:     - assert: { that: "vault_auth.created == False" }
34:     - assert: { that: "vault_auth.failed == False" }
35:     - assert: { that: "vault_auth.rc == 0" }
36:     - name: Enable userpass auth for the third time with change
37:       hashivault_auth_method:
38:         method_type: "userpass"
39:         description: "our userpass"
40:       register: 'vault_auth'
41:     - assert: { that: "vault_auth is changed" }
42:     - assert: { that: "vault_auth.created == False" }
43:     - assert: { that: "vault_auth.rc == 0" }
44:     - name: Enable userpass at a different mount point
45:       hashivault_auth_method:
46:         method_type: "userpass"
47:         mount_point: "another-userpass"
48:       register: 'vault_auth_mount_point'
49:     - assert: { that: "vault_auth_mount_point is changed" }
50:     - assert: { that: "vault_auth_mount_point.rc == 0" }

